@startuml

class Student {
  + StudentID : string
  + BirthDate : date
  + BirthCity : string
  + BirthRegion : string
  + EnrollmentYear : int
}

class Professor {
  + Name : string
  + BirthDate : date
  + BirthCity : string
}

class Faculty {
  + Name : string
  + Type : string
}

class Course {
  + Code : string
  + LectureHours : int
}

class Exam {
  + Grade : float
}

Faculty "1" -- "0..*" Student : enrolls
Faculty "1" -- "0..*" Course : belongs to
Professor "0..*" -- "0..*" Course : teaches
Student "1" -- "0..*" Exam : passes
Course "1" -- "0..*" Exam : is subject of

@enduml

